<?php
require 'config/database.php'; require 'includes/auth.php'; require 'includes/csrf.php'; require_admin();
$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';
 try{
  if($action==='save_post'){
   $id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');$excerpt=trim($_POST['excerpt']??'');$content=trim($_POST['content']??'');$cover=trim($_POST['cover_image']??'');$status=($_POST['status']??'draft')==='published'?'published':'draft';
   if($title===''||$content==='')throw new RuntimeException('El título y el contenido son obligatorios.');
   if($id){$s=$pdo->prepare("UPDATE blog_posts SET title=?,excerpt=?,content=?,cover_image=?,status=?,published_at=IF(?='published',COALESCE(published_at,NOW()),NULL) WHERE id=?");$s->execute([$title,$excerpt,$content,$cover?:null,$status,$status,$id]);}
   else{$s=$pdo->prepare("INSERT INTO blog_posts(title,excerpt,content,cover_image,status,published_at,author_id) VALUES(?,?,?,?,?,IF(?='published',NOW(),NULL),?)");$s->execute([$title,$excerpt,$content,$cover?:null,$status,$status,(int)$_SESSION['user_id']]);}
   $msg='Publicación guardada correctamente.';
  }elseif($action==='delete_post'){
   $s=$pdo->prepare("DELETE FROM blog_posts WHERE id=?");$s->execute([(int)$_POST['id']]);$msg='Publicación eliminada.';
  }elseif($action==='comment_status'){
   $status=($_POST['status']??'hidden')==='visible'?'visible':'hidden';$s=$pdo->prepare("UPDATE blog_comments SET status=? WHERE id=?");$s->execute([$status,(int)$_POST['id']]);$msg='Estado del comentario actualizado.';
  }elseif($action==='delete_comment'){
   $s=$pdo->prepare("DELETE FROM blog_comments WHERE id=?");$s->execute([(int)$_POST['id']]);$msg='Comentario eliminado.';
  }
 }catch(Throwable $e){$err=$e instanceof RuntimeException?$e->getMessage():'No se pudo completar la operación.';}
}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM blog_posts WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:null;}
$posts=$pdo->query("SELECT p.*,u.username FROM blog_posts p LEFT JOIN usuarios u ON u.id=p.author_id ORDER BY p.created_at DESC")->fetchAll();
$comments=$pdo->query("SELECT c.*,u.username,p.title FROM blog_comments c JOIN usuarios u ON u.id=c.user_id JOIN blog_posts p ON p.id=c.post_id ORDER BY c.created_at DESC LIMIT 100")->fetchAll();
?>
<!doctype html><html lang="es" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Administrar blog — SHT</title><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/tienda.css"><link rel="stylesheet" href="css/admin.css"><link rel="stylesheet" href="css/blog.css"></head><body><header class="site-header"><a class="brand" href="index.php"><span class="brand-mark">S</span><span>SHT.</span></a><nav class="main-nav"><a href="admin.php">Panel principal</a><a href="blog.php">Ver blog</a><a href="tienda.php">Tienda</a></nav><div class="header-actions"><span class="admin-user"><?=h($_SESSION['username'])?></span><a class="login-btn" href="logout.php">Cerrar sesión</a></div></header>
<main class="admin-wrap"><div class="admin-title"><p class="eyebrow">CONTENIDO EDITORIAL</p><h1>Administrar <em>blog</em></h1><p class="admin-sub">Crea publicaciones y administra la participación de la comunidad.</p></div><?php if($msg):?><p class="admin-alert success"><?=h($msg)?></p><?php endif;?><?php if($err):?><p class="admin-alert error"><?=h($err)?></p><?php endif;?>
<section class="admin-section" id="editor"><div class="admin-section-head"><div><p class="eyebrow">01 — PUBLICACIONES</p><h2><?=$edit?'Editar publicación':'Nueva publicación'?></h2></div><a class="text-link" href="blog-admin.php#editor">Nueva publicación ↗</a></div>
<form method="post" class="product-form"><?=csrf_field()?><input type="hidden" name="action" value="save_post"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><label class="wide">Título<input name="title" maxlength="180" required value="<?=h($edit['title']??'')?>"></label><label class="wide">Resumen<textarea name="excerpt" rows="2" maxlength="500"><?=h($edit['excerpt']??'')?></textarea></label><label class="wide">Contenido<textarea name="content" rows="12" required><?=h($edit['content']??'')?></textarea></label><label class="wide">URL de imagen de portada (opcional)<input name="cover_image" type="url" value="<?=h($edit['cover_image']??'')?>" placeholder="https://..."></label><label>Estado<select name="status"><option value="draft" <?=($edit['status']??'draft')==='draft'?'selected':''?>>Borrador</option><option value="published" <?=($edit['status']??'')==='published'?'selected':''?>>Publicado</option></select></label><div class="wide form-actions"><button class="button button-primary" type="submit">Guardar publicación</button><?php if($edit):?><a class="text-link" href="blog-admin.php#editor">Cancelar</a><?php endif;?></div></form>
<div class="table-scroll"><table class="admin-table"><thead><tr><th>Título</th><th>Estado</th><th>Fecha</th><th>Acciones</th></tr></thead><tbody><?php foreach($posts as $p):?><tr><td><?=h($p['title'])?></td><td><?=h($p['status']==='published'?'Publicado':'Borrador')?></td><td><?=date('d/m/Y',strtotime($p['created_at']))?></td><td class="actions"><a href="blog-admin.php?edit=<?=(int)$p['id']?>#editor">Editar</a><a href="blog-post.php?id=<?=(int)$p['id']?>" target="_blank">Ver</a><form method="post" onsubmit="return confirm('¿Eliminar esta publicación y sus comentarios?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_post"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="danger">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="admin-section" id="comentarios"><p class="eyebrow">02 — MODERACIÓN</p><h2>Comentarios recientes</h2><div class="table-scroll"><table class="admin-table"><thead><tr><th>Usuario</th><th>Publicación</th><th>Comentario</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($comments as $c):?><tr><td><?=h($c['username'])?></td><td><?=h($c['title'])?></td><td><?=h(mb_strimwidth($c['body'],0,120,'…'))?></td><td><?=h($c['status'])?></td><td class="actions"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="comment_status"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><input type="hidden" name="status" value="<?=$c['status']==='visible'?'hidden':'visible'?>"><button><?=$c['status']==='visible'?'Ocultar':'Mostrar'?></button></form><form method="post" onsubmit="return confirm('¿Eliminar comentario?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_comment"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><button class="danger">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div></section></main><script src="js/app.js"></script></body></html>
